"""Partition R04 into observed open spaces and dense forest, retaining parent IDs."""
import json
from pathlib import Path
from shapely.geometry import Polygon,box
from shapely.ops import unary_union
from shapely import set_precision
root=Path(__file__).resolve().parents[1];c=json.loads((root/'data/campus.json').read_text());a=json.loads((root/'facilities/r04-vegetation/layout.json').read_text());text=(root/'data/road-regions.js').read_text();r=next(r for r in json.loads(text.split('=',1)[1].split(';',1)[0])if r['id']=='R04');parent=Polygon(r['ring'],r['holes']).buffer(0)
def plan(name):
 p=json.loads((root/('data/'+name+'-plan.js')).read_text().split('=',1)[1].rstrip(';\n'));return unary_union([Polygon(r[0],r[1:])for r in p['regions']])
paving=set_precision(plan('motor-pavement').union(plan('sidewalk')),.000001);parent=set_precision(parent,.000001).difference(paving);allBuildings=[b for b in c['places']+c['buildings']if b.get('height')];built=unary_union([Polygon(b['ring']).buffer(.5)for b in allBuildings]);quarter=unary_union([unary_union([Polygon(b['ring'])for b in allBuildings if b['osm']in a['openBuildingIds'][:2]]).convex_hull.buffer(a['forecourtBuffer'])]+[Polygon(b['ring']).buffer(a['forecourtBuffer'])for b in allBuildings if b['osm']==a['openBuildingIds'][2]]+[Polygon(p['ring']).buffer(1.5)for p in c['pedestrianLinks']if 'yongxu'in p['id']]);teaching=unary_union([Polygon(b['ring'])for b in allBuildings if b['osm']in a['teachingBuildingIds']]).convex_hull.buffer(a['teachingBuffer']);lawn=Polygon(c['yongxuLandscape']['lawn']['ring']);records=[];remaining=parent
for id,name,kind,shape in [('R04-L1','詠絮樓內側草皮','lawn',lawn),('R04-O1','食巢・飛燕・詠絮前庭','open',quarter),('R04-O2','高斯・致理・寰宇教學區','open',teaching),('R04-O3','其他建築與附屬設施','open',built)]+[(b['id'],b['name'],'forest',box(-500,b['north'],500,b['south']))for b in a['forestBands']]:
 shape=remaining.intersection(set_precision(shape,.000001)).buffer(0);remaining=remaining.difference(shape)
 parts=[p for p in (shape.geoms if hasattr(shape,'geoms')else[shape])if p.area>.01]
 if not parts:continue
 def ring(r):return[[round(x,6),round(z,6)]for x,z in list(r.coords)[:-1]]
 regions=[[ring(p.exterior)]+[ring(h)for h in p.interiors]for p in parts];largest=max(parts,key=lambda p:p.area);label=largest.representative_point();records.append(dict(id=id,parent='R04',name=name,category=kind,regions=regions,ring=ring(largest.exterior),holes=[ring(h)for h in largest.interiors],boundaryNames=['R04內部校正界','實際鋪面外緣'],roadIds=[],label=[round(label.x,3),round(label.y,3)],area=round(shape.area,3),status='confirmed',confidence='user-observation-with-model-boundaries',note='依使用者現場回饋分類；細分界為方便定位的模型近似。'))
assert remaining.area<.001
result={'reference':a['reference'],'forestSpacing':a['forestSpacing'],'regions':records};(root/'data/r04-vegetation.js').write_text('// Generated by scripts/build-r04-vegetation.py. User-observed vegetation; model subdivision boundaries.\nexport const r04Vegetation='+json.dumps(result,ensure_ascii=False,separators=(',',':'))+';\n');print('Built',len(records),'R04 subregions:',[(r['id'],r['category'],r['area'])for r in records])
